function isTaskLikePrompt(prompt) {
  const lowerPrompt = prompt.toLowerCase().trim();
  const taskKeywords = [
    "create",
    "build",
    "develop",
    "make",
    "generate",
    "write",
    "design",
    "analyze",
    "research",
    "find",
    "search for",
    "compile",
    "organize",
    "plan",
    "schedule",
    "track",
    "monitor",
    "update",
    "sync",
    "integrate",
    "implement",
    "deploy",
    "setup",
    "configure",
    "install",
    "test",
    "execute",
    "run",
    "perform",
    "complete",
    "finish",
    "deliver",
    "produce",
    "construct",
    "assemble",
    "prepare",
    "arrange",
    "format"
  ];
  const taskPhrases = [
    "step by step",
    "step-by-step",
    "stepwise",
    "in steps",
    "with steps",
    "show me how",
    "guide me",
    "walk me through",
    "do this",
    "get this done",
    "handle this",
    "take care of",
    "work on",
    "focus on",
    "tackle",
    "address",
    "solve",
    "automate",
    "script",
    "program",
    "code",
    "build a",
    "create a",
    "make a",
    "develop a",
    "design a"
  ];
  const hasTaskKeyword = taskKeywords.some(
    (keyword) => lowerPrompt.startsWith(keyword) || lowerPrompt.includes(` ${keyword} `) || lowerPrompt.includes(`${keyword} a`) || lowerPrompt.includes(`${keyword} an`)
  );
  const hasTaskPhrase = taskPhrases.some(
    (phrase) => lowerPrompt.includes(phrase)
  );
  const isImperative = /^(create|build|make|develop|write|design|analyze|research|find|search|compile|organize|plan|schedule|track|monitor|update|sync|integrate|implement|deploy|setup|configure|install|test|execute|run|perform|complete|finish|deliver|produce|construct|assemble|prepare|arrange|format)/i.test(prompt);
  const isQuestion = /^(what|when|where|who|why|how|which|is|are|can|could|would|should|will|do|does|did)/i.test(prompt);
  const isConversational = /^(tell me|explain|describe|help me|i need|i want|i\'m looking for|can you|could you|would you)/i.test(prompt);
  if (isQuestion || isConversational) {
    return false;
  }
  if (hasTaskKeyword || hasTaskPhrase || isImperative) {
    return true;
  }
  return prompt.length < 100 && !prompt.includes("?");
}

